def forward(self, x, ve, cos_sin, window_size, prev_kv):
    attn_out, kv_state = self.attn(norm(x), ve, cos_sin, window_size, prev_kv)
    x = x + attn_out
    x = x + self.mlp(norm(x))
    return (x, kv_state)

