def has_ve(layer_idx, n_layer):
    """Use four value embeddings, aligning one with the early full-context layer."""
    if n_layer == 8:
        return layer_idx in (1, 2, 5, 7)
    return layer_idx % 2 == (n_layer - 1) % 2
